 function guideHtml(forcePicker=false){if(!guide)return '<p class="pi-guide-loading">Finding your saved CV evidence…</p>';if(!guide.examples?.length)return `<p>No strong example yet: <a href="${esc(assessment?.id||setup?.assessmentId?'/cv-builder.html?id='+encodeURIComponent(assessment?.id||setup?.assessmentId):'/assessment-start.html')}">here’s how to find one →</a></p>`;if((forcePicker||picker)&&!guide.examples[0]?.templateOnly)return `<div class="pi-card-head"><b>Use one from your CV</b></div><fieldset class="pi-examples"><legend class="sr-only">Choose an example</legend>${guide.examples.map((e,i)=>`<label><input type="radio" name="${forcePicker?'swap':'example'}" value="${i}" ${i===selected?'checked':''}><span><strong>${esc(e.point)}</strong><small>${esc(e.coaching)}</small></span></label>`).join('')}</fieldset><button class="pi-use" type="button" data-action="use">Use this example →</button>`;if(mode==='learn')return answerBuilderHtml();return `<div class="pi-card-head"><b>${follow?'Answer this follow-up':'Your answer in 4 beats'}</b><span>${guide.savedAnswer?'Your saved '+(Number.isFinite(guide.savedAnswer.score)?'answer · '+esc(guide.savedAnswer.score):'application draft'):'from '+esc(sourceLabel(example().source))}</span></div>${example().beats.map((b,i)=>beatHtml(b,i)).join('')}<button class="pi-change" type="button" data-action="change">Change example</button>${answerLink()}`;}
