 function drawGuide(){const built=preparedAnswer?.question===q().q&&preparedAnswer.sourceId===example()?.id;root.classList.toggle('pi-editing',mode==='learn'&&!built&&!picker);root.classList.toggle('pi-built',mode==='learn'&&built);if(mode==='learn'&&phase!=='record'){root.querySelector('.pi-ready').disabled=!example();root.querySelector('.pi-ready').textContent='Looks good · start practising';}root.querySelector('.pi-guide').innerHTML=(activeFixes.length?'<section class="pi-feedback-card"><h2>Keep these fixes in mind</h2>'+activeFixes.map(f=>'<p>'+esc(f.tryText||f.action||f.title)+'</p>').join('')+'</section>':'')+(mode==='learn'?'<div class="pi-coaching-intro">'+reallyAskingCard(personalAsking(reallyAskingFor(q()),guide?.examples?.[0]),/why /i.test(q().q)&&whyFirmFor(firm)?firm:'the interviewer')+'</div>':'')+(coachedQuestion===q().q&&coachedScript?'<button class="pi-ink" type="button" data-action="read-revised">Read your improved script</button>':'')+guideHtml();drawRecordingSections();root.querySelector('.pi-record-fixes').innerHTML=activeFixes.length?'<div class="pi-retry-fixes">'+activeFixes.map(f=>'<p>'+esc(f.title)+': '+esc(f.tryText||f.action||'')+'</p>').join('')+'</div>':'';root.querySelector('.pi-tip').innerHTML=reallyAskingCard(personalAsking(reallyAskingFor(q()),guide?.examples?.[0]),/why /i.test(q().q)&&whyFirmFor(firm)?firm:'the interviewer');root.classList.toggle('pi-script-mode',mode==='learn');root.querySelector('.pi-pinned-note').textContent=mode==='learn'?'Tap any line to change it · gaps can wait':'The 4 beats stay pinned while you record';}
 async function loadGuide(){if(preparedAnswer?.question===q().q){guide={...(guide||{}),examples:[preparedAnswer.example],locked:!!free};selected=0;picker=false;drawGuide();return;}if(rewritePractice&&rewritePractice.question===q().q){preparedAnswer={question:q().q,sourceId:rewritePractice.example.id,example:rewritePractice.example};guide={examples:[rewritePractice.example],tip:'Use your own natural words. Keep the specific action and finding.'};selected=0;picker=false;drawGuide();return;}const version=++guideVersion;guide=null;selected=0;picker=false;drawGuide();try{const r=await fetch('/api/interview-guide',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({dailyId:daily?.dailyId,question:q().q,kind:q().kind,firm,role:bank?.roles[setup?.role]?.label||profile?.route||profile?.division||'',assessmentId:assessment?.id||setup?.assessmentId||new URLSearchParams(location.search).get('id'),taster:free,autoSavedAnswers:true,savedAnswerId:q().savedAnswerId,useConfirmedDetails,useSavedAnswers,followUpOf:follow?{question:follow.originalQuestion,sourceId:follow.sourceId}:null})});const d=await r.json();if(version!==guideVersion)return;if(!r.ok)throw Error(d.error||'Your guide could not load.');guide=d;picker=false;drawGuide();}catch(e){if(version!==guideVersion)return;root.querySelector('.pi-guide').innerHTML='<p>'+esc(e.message)+'</p><button type="button" data-action="retry-guide">Try again</button>';}}
 function startThinkTimer(){const deadline=Date.now()+remaining*1000;setPhase('think');root.querySelector('.pi-ready').disabled=false;root.querySelector('.pi-status').textContent='Thinking time · prepare your answer.';timer=setInterval(()=>{if(mode!=='test'&&(root.querySelector('dialog[open]')||document.hidden||root.querySelector('.pi-inline-detail textarea:focus,.pi-answer-builder textarea:focus'))){root.querySelector('.pi-think-clock').textContent=fmt(remaining)+' · paused while preparing';return;}remaining=mode==='test'?Math.max(0,Math.ceil((deadline-Date.now())/1000)):remaining-1;root.querySelector('.pi-think-clock').textContent='Thinking time · '+fmt(remaining);if(remaining<=0){clearInterval(timer);beginRecording();}},1000);}
 async function playQuestion(){const version=++voiceVersion;clearInterval(timer);window.DeskNaturalVoice?.cancel();setPhase('listen');root.querySelector('.pi-ready').disabled=false;root.querySelector('.pi-think-clock').textContent='Listen to the question';root.querySelector('.pi-status').textContent='Reading your question… You can answer whenever you’re ready.';const ok=await window.DeskNaturalVoice?.speak(q().q,free?undefined:assessment?.id);if(version!==voiceVersion)return;if(ok){remaining=30;if(mode==='test')startThinkTimer();else{setPhase('think');root.querySelector('.pi-think-clock').textContent='Build your answer · no time limit';}}else{if(mode==='test')startThinkTimer();else setPhase('think');root.querySelector('.pi-status').textContent=window.DeskNaturalVoice?.error||'Question audio unavailable. Read the question and continue when ready.';}}
