 let connecting=null;async function connect(audioOnly=false){if(connecting)return connecting;connecting=(async()=>{if(audioOnly)await window.DeskInterviewMedia.connect(false);else await window.DeskInterviewMedia.connectForAnswer();return typeof stream!=='undefined'&&stream?.getAudioTracks().some(t=>t.readyState==='live');})();try{return await connecting}finally{connecting=null}}
 async function beginRecording(){if(busy||!['think','listen'].includes(phase))return;if(mode==='learn'&&(!preparedAnswer||preparedAnswer.question!==q().q||preparedAnswer.sourceId!==example()?.id)&&!rewritePractice){root.querySelector('.pi-status').textContent='Your CV guide is loading. Please try again when it is ready.';return;}busy=true;voiceVersion++;window.DeskNaturalVoice?.cancel();setPhase('think');clearInterval(timer);root.querySelector('.pi-status').textContent='Checking camera and microphone…';try{if(!await connect()){root.querySelector('.pi-status').textContent='Allow microphone access, choose microphone only, or type your answer.';return;}document.body.dataset.deskMode=mode;start();clearInterval(tick);if(recorder?.state!=='recording')throw Error('Recording could not start. Please try again.');setPhase('record');navigator.vibrate?.(10);recordingSection=0;elapsed=0;const began=Date.now();root.querySelector('.pi-recording-badge span').textContent=`Q${index+1} of ${list.length}`;root.querySelector('.pi-record-meta').innerHTML=firmMark(firm)+'<span>'+esc(firm)+' · '+esc(type())+'</span>';root.querySelector('.pi-overlay h2').textContent=q().q;drawGuide();updateTimer();timer=setInterval(()=>{elapsed=Math.floor((Date.now()-began)/1000);updateTimer();if(elapsed>=120)finishRecording();},250);}catch(e){root.querySelector('.pi-status').textContent=e.message;}finally{busy=false;}}
 function updateTimer(){root.querySelector('.pi-elapsed').textContent=fmt(elapsed);const bar=root.querySelector('.pi-time [role=progressbar]');bar.setAttribute('aria-valuenow',String(Math.min(120,elapsed)));bar.querySelector('i').style.width=Math.min(100,elapsed/120*100)+'%';}
 async function finishRecording(){navigator.vibrate?.(10);if(phase!=='record')return;clearInterval(timer);stop();setPhase(mode==='test'?'loading':'review');if(mode==='test'){root.querySelector('.pi-loading h1').textContent='Keeping your answer.';root.querySelector('.pi-loading p').textContent='Finishing the transcript. Feedback comes at the end of your run.';}root.querySelector('.pi-review-status').textContent='Finishing your transcript…';const button=root.querySelector('.pi-assess');button.disabled=true;await new Promise(r=>setTimeout(r,200));const began=Date.now();while(window.DeskTranscriptPending&&Date.now()-began<60000)await new Promise(r=>setTimeout(r,250));button.disabled=false;if(mode==='test'){if(!captureAnswer())skippedAnswers.set(index,{question:q().q,transcript:transcript.value});advanceQuestion();return;}root.querySelector('.pi-review-status').textContent=window.DeskTranscriptPending?'Transcription is still running.':transcript.value.trim()?'Review your transcript before assessment.':'No transcript was captured. Retry transcription below, or type your answer.';const host=root.querySelector('.pi-playback');host.replaceChildren();if(recordingUrl){const playback=document.createElement('video');playback.controls=true;playback.playsInline=true;playback.src=recordingUrl;playback.style.width='100%';playback.setAttribute('aria-label','Play your recorded answer');host.append(playback);}}
 function captureAnswer(){skippedAnswers.delete(index);if(window.DeskTranscriptPending){root.querySelector('.pi-review-status').textContent='Please wait for transcription to finish.';return null;}const text=transcript.value.trim();if(text.split(/\s+/).length<20){root.querySelector('.pi-review-status').textContent='Add at least 20 words answering this question.';return null;}return rememberInterviewAnswer(sessionAnswers,index+':'+(follow?follow.question:'main'),{dailyId:daily?.dailyId,question:q().q,kind:q().kind,transcript:text,seconds:elapsed,firm,role:profile.targetSector||'',cv:$('cvText').value,assessmentId:assessment?.id||setup?.assessmentId,evidenceGuide:true,savedAnswerId:list[index].savedAnswerId||savedForQuestion(q())?.id,followUpOf:follow?{question:follow.originalQuestion,answer:follow.originalAnswer}:null});}
