 async function assess(){if(busy)return;const entry=captureAnswer();if(!entry)return;busy=true;setPhase('loading');root.querySelector('.pi-loading h1').textContent='Reviewing your evidence.';try{feedback=entry.feedback||await requestFeedback({...entry.payload,...(feedback?.coachingPending&&feedback.attemptId?{resumeAttemptId:feedback.attemptId}:{})},(event,data)=>{if(mode==='test')return;if(event==='score'){feedback={...data.feedback,attemptId:data.answerId,coachingPending:true};}else if(event==='beats'&&feedback?.coachingPending){feedback.beatReview=data.beatReview;}else if(event==='fix'&&feedback?.coachingPending){feedback.improvement??={fixes:[],target:70};feedback.improvement.fixes=feedback.improvement.fixes.filter(f=>f.dimension!==data.dimension);feedback.improvement.fixes.push(data.fix);}else return;drawFeedback();setPhase('feedback');});entry.feedback=feedback;trackPractice('question_complete');recordAttempt(feedback,entry.payload);drawFeedback();setPhase('feedback');}catch(error){if(feedback?.coachingPending){feedback.coachingError=error.message;drawFeedback();setPhase('feedback');}else{setPhase('review');root.querySelector('.pi-review-status').textContent=error.message;}}finally{busy=false;}}
