 function polishFeedbackScreen(){const panel=root.querySelector('.pi-feedback'),phone=matchMedia('(max-width:900px)').matches;if(!phone)panel.querySelectorAll('.pi-deep-workspace>details,.pi-rewrite-details,.pi-feedback-details').forEach(d=>d.open=true);const score=panel.querySelector('.pi-score-row>b');if(!score)return;const target=Number(feedback.overall),old=historyForCurrent().filter(a=>a.attemptId!==feedback.attemptId),best=old.length?Math.max(...old.map(a=>a.overall)):null;score.closest('.pi-score').classList.toggle('pi-new-best',best!==null&&target>best);if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;if(panel.dataset.revealed===String(feedback.attemptId))return;panel.dataset.revealed=String(feedback.attemptId);const started=performance.now();function frame(now){if(!score.isConnected)return;const progress=Math.min(1,(now-started)/600);score.textContent=String(Math.round(target*progress));if(progress<1)requestAnimationFrame(frame);}requestAnimationFrame(frame);if(phone)navigator.vibrate?.(10);}


