 function nodeComplete(error=''){setPhase('feedback');if(mode==='test'&&!error){root.querySelector('.pi-feedback').innerHTML=renderRealSummary({answers:sessionAnswers,skipped:skippedAnswers});return;}const pending=sessionAnswers.filter(e=>!e.feedback),reviewed=sessionAnswers.filter(e=>e.feedback),average=reviewed.length?Math.round(reviewed.reduce((sum,e)=>sum+Number(e.feedback.overall||0),0)/reviewed.length):null;root.querySelector('.pi-feedback').innerHTML=`<header class="pi-light-top"><a href="/">The Desk</a><a href="/my.html">Exit</a></header><div class="pi-content"><div class="pi-k">Your interview</div><h1>${pending.length?'Ready to review your answers?':'Your interview, reviewed.'}</h1><p>${sessionAnswers.length} answers captured · ${reviewed.length} assessed · ${skippedAnswers.size} skipped.</p>${error?`<p role="alert">${esc(error)} Completed reviews are kept; retry reviews only the remaining answers.</p>`:''}${average!==null?`<div class="pi-score"><b>${average}</b><span>/100 · average of reviewed answers</span><p>Interview practice only. Your readiness score is unchanged.</p></div>`:''}${[...skippedAnswers.values()].map(e=>`<section class="pi-feedback-card"><h2>Skipped question</h2><p>${esc(e.question)}</p><p>No score was assigned.</p></section>`).join('')}${sessionAnswers.map((e,i)=>`<section class="pi-feedback-card"><h2>Answer ${i+1}</h2><p>${esc(e.payload.question)}</p>${e.feedback?`<b>${esc(e.feedback.overall)}/100</b><p>${esc(e.feedback.verdict||'')}</p>${(e.feedback.fixes||[]).slice(0,2).map(f=>`<p>${esc(f.fix)}</p>`).join('')}`:'<p>Ready to assess.</p>'}<details><summary>Your transcript</summary><p>${esc(e.payload.transcript)}</p></details></section>`).join('')}${pending.length?'<button class="pi-ink pi-next" type="button" data-action="assess-all">Assess all answers →</button><p>Each answer uses your normal interview allowance. Previously reviewed answers are kept.</p>':'<p>Your reviewed answers are saved in My Desk.</p>'}<a class="pi-link" href="/my.html">Back to My Desk →</a></div>`;}

